const item = $input.first();
const pdf = item.binary?.Invoice_PDF;
const fields = item.json.body ?? item.json;
const missing = ['Your Name', 'Your Email', 'Currency'].filter((key) => !fields[key]);
// n8n 2.x keeps binary data on disk; read the real bytes, never binary.data.
let pdfBytes = 0;
if (pdf) {
  try { pdfBytes = (await this.helpers.getBinaryDataBuffer(0, 'Invoice_PDF')).length; } catch (error) { pdfBytes = 0; }
}
const uuid4 = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => { const r = Math.floor(Math.random() * 16); return (c === 'x' ? r : (r & 3) | 8).toString(16); });
const runId = item.json.headers?.['x-replay-run-id'] || uuid4();
const inputRef = item.json.headers?.['x-replay-input-id'] || '';
if (!pdf || pdfBytes === 0 || missing.length || pdfBytes > Number(item.json.max_pdf_bytes)) {
  return [{ json: { ...item.json, run_id: runId, input_ref: inputRef, error_stage: 'intake', error_node: 'H1 Intake Guard',
    error_code: 'reject:intake', error_message: 'missing required form data or PDF, or PDF exceeds size cap',
    terminal_status: 'rejected' } }];
}
return [{ json: { ...item.json, run_id: runId, input_ref: inputRef, pdf_bytes: pdfBytes, submitter_email: fields['Your Email'],
  form_currency: fields.Currency, notes: fields.Notes || '' }, binary: item.binary }];

// SHA256-BEGIN — dependency-free SHA-256 over bytes; tests/test_hardened.py checks it against Python hashlib.
function sha256Hex(bytes) {
  const K = [0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2];
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const len = bytes.length;
  const total = Math.ceil((len + 9) / 64) * 64;
  const msg = new Uint8Array(total);
  msg.set(bytes);
  msg[len] = 0x80;
  const bits = len * 8;
  const view = new DataView(msg.buffer);
  view.setUint32(total - 8, Math.floor(bits / 0x100000000));
  view.setUint32(total - 4, bits >>> 0);
  const W = new Uint32Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < total; off += 64) {
    for (let t = 0; t < 16; t++) W[t] = view.getUint32(off + t * 4);
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(W[t - 15], 7) ^ rotr(W[t - 15], 18) ^ (W[t - 15] >>> 3);
      const s1 = rotr(W[t - 2], 17) ^ rotr(W[t - 2], 19) ^ (W[t - 2] >>> 10);
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[t] + W[t]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  return H.map((x) => x.toString(16).padStart(8, '0')).join('');
}
// SHA256-END

const item = $input.first();
const bytes = await this.helpers.getBinaryDataBuffer(0, 'Invoice_PDF');
return [{ json: { ...item.json, content_sha256: sha256Hex(new Uint8Array(bytes)) }, binary: item.binary }];

const source = $('H1 Intake Guard').first();
const text = String($json.text || '');
const estimateIn = Math.ceil(text.length / 3);
const cfg = source.json;
const estUsd = (estimateIn * Number(cfg.llm_price_in_per_mtok) + Number(cfg.max_output_tokens) * Number(cfg.llm_price_out_per_mtok)) / 1000000;
if (text.length > Number(cfg.max_input_chars)) return [{ json: { ...cfg, content_sha256: $('H1 PDF SHA-256').first().json.content_sha256, error_stage: 'extract', error_code: 'reject:capped', error_message: 'PDF text exceeds input cap', capped: 1, terminal_status: 'rejected' } }];
return [{ json: { ...cfg, content_sha256: $('H1 PDF SHA-256').first().json.content_sha256, pdf_text: text, est_tokens_in: estimateIn, est_usd: estUsd } }];

const source = $('H4 Text Cap').first().json;
const used = Number($('H5 Ledger Sum').first().json.usd || 0);
const calls = Number($json.count || 0);
if (used + Number(source.est_usd) > Number(source.run_usd_cap)) return [{ json: { ...source, error_stage: 'extract', error_code: 'reject:capped', error_message: 'run spend cap would be exceeded', capped: 1, terminal_status: 'rejected' } }];
if (calls >= Number(source.llm_max_rpm)) return [{ json: { ...source, error_stage: 'extract', error_code: 'reject:capped', error_message: 'rate cap reached after one check', capped: 1, terminal_status: 'rejected' } }];
return [{ json: { ...source, usd_so_far: used, calls_last_60s: calls } }];

const source = $('H5 Spend and Rate Gate').first().json;
const usage = $json.usage || {};
const tokensIn = Number(usage.prompt_tokens || 0);
const tokensOut = Number(usage.completion_tokens || 0);
const usd = (tokensIn * Number(source.llm_price_in_per_mtok) + tokensOut * Number(source.llm_price_out_per_mtok)) / 1000000;
return [{ json: { ...source, extracted_json: $json.choices?.[0]?.message?.content || '', tokens_in: tokensIn, tokens_out: tokensOut, usd } }];

const src = $('H1 Intake Guard').first().json;
const inp = $input.first().json || {};
const err = inp.error_code ? inp : {};
const raw = err.error_message || (inp.error && (inp.error.message || inp.error)) || 'external call failed';
return [{ json: { run_id: src.run_id || '', input_ref: src.input_ref || '', stage: err.error_stage || 'external',
  node: err.error_node || 'external call', code: err.error_code || 'error:external', message: String(raw).slice(0, 300),
  capped: err.capped ? 1 : 0 } }];

// NORM-BEGIN — ARCHITECTURE §3.5; tests/test_hardened.py runs the §3.5 vectors on this block under node.
const SUFFIXES = new Set(['ltd', 'limited', 'llc', 'inc', 'incorporated', 'plc', 'gmbh', 'ag', 'sa', 'sas', 'sarl',
  'srl', 'bv', 'nv', 'co', 'corp', 'corporation', 'company']);
function invoiceNoNorm(value) {
  if (value === null || value === undefined) return '';
  return String(value).normalize('NFKC').trim().toUpperCase().replace(/\s+/gu, '');
}
function vendorNorm(value) {
  if (value === null || value === undefined) return '';
  const text = String(value).normalize('NFKC').toLowerCase().replace(/&/g, 'and')
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
  const parts = text ? text.split(' ') : [];
  while (parts.length && SUFFIXES.has(parts[parts.length - 1])) parts.pop();
  return parts.join(' ');
}
function dedupeKey(invoiceNo, vendor, currency) {
  const a = invoiceNoNorm(invoiceNo), b = vendorNorm(vendor);
  if (!a || !b || !currency) return '';
  return a + '|' + b + '|' + currency;
}
// NORM-END

const src = $('H7 Cost Ledger Record').first().json;
const isNum = (v) => typeof v === 'number' && Number.isFinite(v);
const reject = (message) => [{ json: { ...src, route: 'reject', error_stage: 'validate', error_node: 'H8 Schema Gate',
  error_code: 'reject:schema', error_message: message, terminal_status: 'rejected' } }];
let data;
try { data = JSON.parse(src.extracted_json || ''); } catch (error) { return reject('model output is not json'); }
if (!data || typeof data !== 'object' || Array.isArray(data)) return reject('model output is not an object');
if (typeof data.invoice_no !== 'string' || !data.invoice_no.trim()) return reject('invoice_no missing');
if (typeof data.vendor !== 'string' || !data.vendor.trim()) return reject('vendor missing');
if (!isNum(data.total)) return reject('total missing or not a number');
if (!Array.isArray(data.line_items) || data.line_items.length === 0) return reject('line_items empty');
if (data.line_items.some((line) => !line || !isNum(line.line_total))) return reject('line_total missing');
for (const key of ['subtotal', 'tax']) {
  if (data[key] !== null && data[key] !== undefined && !isNum(data[key])) return reject(key + ' is not a number');
}
// H9 foot check, in cents.
const cents = (v) => Math.round(Number(v) * 100);
const lineSum = data.line_items.reduce((sum, line) => sum + cents(line.line_total), 0);
const subtotal = isNum(data.subtotal) ? cents(data.subtotal) : lineSum;
const tax = isNum(data.tax) ? cents(data.tax) : 0;
const reasons = [];
if (Math.abs(lineSum - subtotal) > 1) reasons.push('line totals do not equal subtotal');
if (Math.abs(subtotal + tax - cents(data.total)) > 1) reasons.push('subtotal plus tax does not equal total');
const currency = ['USD', 'EUR', 'GBP'].includes(data.currency) ? data.currency : null;
if (!currency) reasons.push('currency missing or not USD, EUR, GBP');
if (!data.invoice_date || !/^\d{4}-\d{2}-\d{2}$/.test(String(data.invoice_date))) reasons.push('invoice_date missing or not ISO');
const formCurrency = String(src.form_currency || '').split('—')[0].trim().toUpperCase();
if (currency && formCurrency && formCurrency !== currency) reasons.push('form currency differs from document');
const key = dedupeKey(data.invoice_no, data.vendor, currency);
if (!key) reasons.push('no dedupe key');
return [{ json: { ...src, pdf_text: undefined, invoice: { ...data, currency }, vendor_norm: vendorNorm(data.vendor),
  dedupe_key: key, route: reasons.length ? 'review' : 'act', review_reason: reasons.join('; ') } }];

const gate = $('H8 Schema Gate').first().json;
return gate.invoice.line_items.map((line, index) => ({ json: {
  run_id: gate.run_id, dedupe_key: gate.dedupe_key, line_key: gate.dedupe_key + '#' + (index + 1), line_no: index + 1,
  description: String(line.description ?? ''), quantity: line.quantity ?? '', unit_price: line.unit_price ?? '',
  line_total: line.line_total } }));

const gate = $('H8 Schema Gate').first().json;
const inv = gate.invoice;
return [{ json: { run_id: gate.run_id, dedupe_key: gate.dedupe_key, content_sha256: gate.content_sha256,
  invoice_no: inv.invoice_no, vendor: inv.vendor, vendor_norm: gate.vendor_norm, invoice_date: inv.invoice_date,
  currency: inv.currency, subtotal: inv.subtotal ?? '', tax: inv.tax ?? '', total: inv.total,
  line_count: inv.line_items.length, submitter_email: gate.submitter_email } }];

const gate = $('H8 Schema Gate').first().json;
const inv = gate.invoice;
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const allow = String(gate.report_recipient_allowlist || '').split(',').map((d) => d.trim().toLowerCase()).filter(Boolean);
const to = String(gate.submitter_email || '').trim();
const domain = to.includes('@') ? to.split('@').pop().toLowerCase() : '';
const rows = inv.line_items.map((l) => '<tr><td>' + esc(l.description) + '</td><td>' + esc(l.line_total) + '</td></tr>').join('');
const html = '<h1>Invoice recorded</h1><p>' + esc(inv.vendor) + ' ' + esc(inv.invoice_no) + ' ' + esc(inv.invoice_date) +
  ' ' + esc(inv.currency) + ' ' + esc(inv.total) + '</p><table>' + rows + '</table>';
const subject = ('Invoice recorded ' + String(inv.invoice_no) + ' ' + String(inv.vendor)).replace(/[\r\n<>]/g, ' ').slice(0, 150);
return [{ json: { run_id: gate.run_id, to, subject, html, send: allow.includes(domain) } }];

const done = (name) => { try { return $(name).isExecuted; } catch (error) { return false; } };
const pick = (name) => (done(name) ? $(name).first().json : {});
const intake = pick('H1 Intake Guard');
const gate = pick('H8 Schema Gate');
const cost = pick('H7 Cost Ledger Record');
const error = pick('E Build Error Record');
let status = 'duplicate_skip';
let stage = 'intake';
if (done('E Build Error Record')) { status = String(error.code || '').startsWith('reject') ? 'rejected' : 'error'; stage = error.stage || 'record'; }
else if (done('H13 Header Append')) { status = 'committed'; stage = 'act'; }
else if (done('H15 Review Append')) { status = 'review'; stage = 'approve'; }
else if (done('H11 Dedupe Lookup')) { stage = 'act'; }
return [{ json: { run_id: intake.run_id || '', input_ref: intake.input_ref || '', execution_id: String($execution.id),
  stage, node: 'H16 Audit Record', ok: status === 'error' ? 0 : 1, status,
  content_sha256: pick('H1 PDF SHA-256').content_sha256 || '', dedupe_key: gate.dedupe_key || '',
  tokens_in: cost.tokens_in ?? 0, tokens_out: cost.tokens_out ?? 0, usd: cost.usd ?? 0, duration_ms: '' } }];
